<?php
use PHPUnit\Framework\TestCase;

/** Validates actual retained executions; never generates expected run/replay fixtures. */
class B19ArchivedExecutedEvidenceProofTest extends TestCase
{
    private static $bundle;
    private static function root(): string {return dirname(__DIR__,3);}
    private static function json($p): array {return json_decode(file_get_contents($p),true,512,JSON_THROW_ON_ERROR);}
    private static function issued($number): array {
        $p=glob(self::root().'/docs/market_data/records/evidence/E-MD-B19-A001-'.$number.'_*.json')[0];$d=self::json($p);$a=$d['raw_artifacts'];$root=self::root().'/'.$a['dir'];if(hash_file('sha256',$root.'/'.$a['inventory'])!==$a['inventory_sha256'])throw new \RuntimeException('issued inventory corrupt');return [$root,$a];
    }
    private static function retained($base,array $meta,$p): array {if(!isset($meta['files'][$p])||hash_file('sha256',$base.'/'.$p)!==$meta['files'][$p]['sha256'])throw new \RuntimeException('retained execution hash mismatch');return self::json($base.'/'.$p);}
    private static function bundle(): array {
        if(self::$bundle!==null)return self::$bundle;[$r,$a]=self::issued('023');[$q,$z]=self::issued('022');$out=[];
        foreach(['run'=>'normal','held'=>'held'] as $key=>$dir){$b='pipeline_artifacts/'.$dir.'/';$out[$key]=['kind'=>'ACTUAL','path'=>$r.'/'.$b,'data'=>self::retained($r,$a,$b.'run_summary.json'),'manifest'=>self::retained($r,$a,$b.($key==='run'?'publication_manifest.json':'evidence_pack.json')),'events'=>self::retained($r,$a,$b.'run_event_summary.json'),'source'=>self::retained($r,$a,$b.'authoritative_inputs_before_export.json')];}
        $b='pipeline_artifacts/replay_mariadb/';$out['replay']=['kind'=>'ACTUAL','path'=>$q.'/'.$b,'data'=>self::retained($q,$z,$b.'replay_result.json'),'source'=>self::retained($q,$z,$b.'authoritative_inputs.json'),'fixture'=>self::retained($q,$z,$b.'fixture_expected_replay_result.json')];
        $raw=self::root().'/storage/app/market-data/evidence/MD-B19-A001';$out['correction']=['kind'=>'ACTUAL','path'=>$raw.'/E024_changed_','data'=>self::json($raw.'/E024_changed_correction_evidence.json'),'source'=>self::json($raw.'/E024_changed_sources_before_export.json')];
        $out['test']=['kind'=>'ACTUAL','path'=>$raw.'/E024_green_real_correction_complete','data'=>self::json($raw.'/E024_green_real_correction_complete.execution.json'),'stdout'=>file_get_contents($raw.'/E024_green_real_correction_complete.txt'),'test_id'=>'B19CorrectionMariaDbProofTest::test_real_changed_unchanged_failed_and_historical_correction','fixture_family'=>'r0025-synthetic-v2-candidate-v5; separately controlled correction106/107 inputs'];
        return self::$bundle=$out;
    }
    private function issues(array $b): array {
        $bad=[];foreach(['run','held','correction','replay','test'] as $k){if(!isset($b[$k])){$bad[]=$k;continue;}if(($b[$k]['kind']??null)!=='ACTUAL'||strpos(str_replace('\\','/',$b[$k]['path']??''),str_replace('\\','/',self::root()).'/storage/app/market-data/evidence/MD-B19-A001/')!==0)$bad[]=$k.'.archive';}
        if(count($b)!==5)return array_merge($bad,['minimum_classes']);
        if($bad)return $bad;
        foreach(['run','held'] as $k){$p=$b[$k]['data'];$s=$b[$k]['source'];if(empty($p['run_id'])||(int)$p['run_id']!==(int)$s['run']['run_id']||$p['terminal_status']!==$s['run']['terminal_status'])$bad[]=$k.'.identity';}
        if($b['run']['data']['terminal_status']!=='SUCCESS'||$b['run']['data']['publishability_state']!=='READABLE')$bad[]='readable';if(!in_array($b['held']['data']['terminal_status'],['HELD','FAILED'],true))$bad[]='held';
        $p=$b['correction']['data'];$s=$b['correction']['source'];if(empty($p['correction_id'])||(int)$p['correction_id']!==(int)$s['correction']['correction_id']||$p['prior_run_id']===$p['new_run_id']||!$p['publication_switch'])$bad[]='correction.identity';foreach(['bars_batch_hash','indicators_batch_hash','eligibility_batch_hash'] as $f)if($p['old_hashes'][$f]!==$s['prior'][$f]||$p['new_hashes'][$f]!==$s['replacement'][$f])$bad[]='correction.hash';
        $p=$b['replay']['data'];$s=$b['replay']['source'];if(empty($p['replay_id'])||$p['comparison_result']!==$b['replay']['fixture']['comparison_result']||$p['bound_inputs']['config_snapshot_hash']!==hash('sha256',$s['config_snapshot']['resolved_config_json']))$bad[]='replay';
        $t=$b['test'];if($t['data']['exit_code']!==0||hash('sha256',$t['stdout'])!==$t['data']['output_sha256']||!preg_match('/OK \(\d+ tests?, \d+ assertions?\)/',$t['stdout'])||!in_array('tests/Unit/MarketData/B19CorrectionMariaDbProofTest.php',$t['data']['command'],true))$bad[]='test';
        return array_values(array_unique($bad));
    }
    public static function rules(): array {$out=[];foreach([6,7,8,9,10,11,13,14,15,16,17,18,20,21,22,23,24,25,27,28,29,30,31,33,34,35,36,38,39,40,41,42,43,61] as $n)$out['R'.$n]=[$n];return $out;}
    /** @dataProvider rules */
    public function test_each_archived_obligation_has_actual_independent_source_and_execution(int $n): void {
        $b=self::bundle();$this->assertSame([],$this->issues($b),'MD-S062-R'.str_pad($n,4,'0',STR_PAD_LEFT));$run=$b['run'];$c=$b['correction'];$q=$b['replay'];$t=$b['test'];
        $oracle=self::json(self::root().'/tests/fixtures/replay/r0025-synthetic-v2-candidate-v5/expected/expected_publication_manifest.json');
        switch($n){case 6:$this->assertSame('SUCCESS',$run['data']['terminal_status']);break;case 7:$this->assertSame('HELD',$b['held']['data']['terminal_status']);break;case 8:case 20:$this->assertSame((int)$c['source']['correction']['correction_id'],$c['data']['correction_id']);break;case 9:case 27:$this->assertSame('PUBLICATION_EXACT',$q['data']['replay_mode']);$this->assertGreaterThan(0,$q['data']['replay_id']);break;case 10:case 33:$this->assertStringContainsString('B19CorrectionMariaDbProofTest::test_real_changed',$t['test_id']);break;case 13:$this->assertSame($run['source']['run']['trade_date_requested'],$run['data']['trade_date_requested']);break;case 14:$this->assertSame($oracle['publication_manifest_hash'],$run['manifest']['publication_manifest_hash']);break;case 15:$this->assertSame($oracle['payload']['artifacts']['bars'],$run['data']['bars_batch_hash']);break;case 16:$this->assertSame(count($run['source']['events']),$run['events']['event_count']);break;case 17:$this->assertSame(hash('sha256',$run['source']['config_snapshot']['resolved_config_json']),$run['manifest']['config_snapshot_hash']);break;case 18:$this->assertSame($run['source']['run']['created_at'],$run['data']['created_at']);break;case 21:$this->assertSame((int)$c['source']['prior']['publication_id'],$c['data']['prior_publication']['publication_id']);break;case 22:$this->assertSame((int)$c['source']['replacement']['publication_id'],$c['data']['new_publication']['publication_id']);break;case 23:case 24:$this->assertNotSame($c['data']['old_hashes']['bars_batch_hash'],$c['data']['new_hashes']['bars_batch_hash']);break;case 25:$this->assertTrue($c['data']['publication_switch']);break;case 28:$this->assertSame('MATCH',$q['data']['comparison_result']);break;case 29:$this->assertSame(hash('sha256',$q['source']['config_snapshot']['resolved_config_json']),$q['data']['bound_inputs']['config_snapshot_hash']);break;case 30:$this->assertSame($oracle['payload']['artifacts']['bars'],$q['data']['bars_batch_hash']);break;case 31:$this->assertSame('PASS',$q['data']['replay_status']);$this->assertNotEmpty($q['data']['comparison_note']);break;case 34:$this->assertStringContainsString('candidate-v5',$t['fixture_family']);break;case 35:case 36:$this->assertSame(0,$t['data']['exit_code']);$this->assertMatchesRegularExpression('/OK \(2 tests, \d+ assertions\)/',$t['stdout']);break;case 38:$this->assertGreaterThan(0,$run['data']['run_id']);$this->assertGreaterThan(0,$c['data']['correction_id']);break;case 39:$this->assertSame($oracle['payload']['artifacts']['bars'],$c['data']['old_hashes']['bars_batch_hash']);break;case 40:$this->assertStringContainsString('B19CorrectionMariaDbProofTest.php',implode(' ',$t['data']['command']));break;case 41:$this->assertStringContainsString('/storage/app/market-data/evidence/MD-B19-A001/',$c['path']);break;default:$this->assertCount(5,$b);}
    }
    public static function negativeCases(): array {$a=[];foreach(['examples','missing_class','foreign_run','hash_swap','replay_config','test_stdout','wrong_path'] as $c)$a[$c]=[$c];return $a;}
    /** @dataProvider negativeCases */
    public function test_missing_illustrative_or_contradictory_archives_are_not_admitted(string $case): void {$b=self::bundle();switch($case){case 'examples':$b['run']['kind']='ILLUSTRATIVE';break;case 'missing_class':unset($b['correction']);break;case 'foreign_run':$b['run']['data']['run_id']=0;break;case 'hash_swap':$b['correction']['data']['new_hashes']=$b['correction']['data']['old_hashes'];break;case 'replay_config':$b['replay']['data']['bound_inputs']['config_snapshot_hash']=str_repeat('0',64);break;case 'test_stdout':$b['test']['stdout']='OK (2 tests, 999 assertions)';break;case 'wrong_path':$b['test']['path']='examples/illustrative';break;}$this->assertNotEmpty($this->issues($b),$case);}
}
